from pydantic import BaseModel, Field
from typing import List, Dict, Any, Optional

class ImagePayload(BaseModel):
    image_bytes: bytes = Field(..., description="Image content in bytes")

class LabelResult(BaseModel):
    name: str
    confidence: float

class DetectLabelsResponse(BaseModel):
    labels: List[LabelResult]

class TextDetection(BaseModel):
    detected_text: str
    confidence: float
    bounding_box: Dict[str, Any]

class DetectTextResponse(BaseModel):
    text_detections: List[TextDetection]

class ModerationLabel(BaseModel):
    name: str
    parent_name: Optional[str] = None
    confidence: float

class DetectModerationLabelsResponse(BaseModel):
    moderation_labels: List[ModerationLabel]

class ImageDescriptionResponse(BaseModel):
    description: str

class ImageSummaryRequest(BaseModel):
    detected_labels: List[LabelResult]
    detected_text: Optional[List[TextDetection]] = None
    moderation_labels: Optional[List[ModerationLabel]] = None
    description: Optional[str] = None

class ImageSummaryResponse(BaseModel):
    summary: str

class TranslateTextRequest(BaseModel):
    text: str
    source_language: str
    target_language: str

class TranslateTextResponse(BaseModel):
    translated_text: str

class TextSafetyRequest(BaseModel):
    text: str

class TextSafetyResponse(BaseModel):
    is_unsafe: bool
    safety_details: Dict[str, Any]

class ArchiveAssetRequest(BaseModel):
    image_name: str
    image_bytes: bytes
    analysis_results: Dict[str, Any]
    caption: str

class ArchiveAssetResponse(BaseModel):
    archive_url: str

import boto3
from typing import Dict, Any

def get_rekognition_client(config: Dict[str, Any]) -> Any:
    """Initializes and returns an AWS Rekognition client."""
    region_name = config.get("region")
    if not region_name:
        raise ValueError("AWS region must be provided in config.")
    return boto3.client("rekognition", region_name=region_name)

def get_bedrock_runtime_client(config: Dict[str, Any]) -> Any:
    """Initializes and returns an AWS Bedrock Runtime client."""
    region_name = config.get("region")
    if not region_name:
        raise ValueError("AWS region for Bedrock must be provided in config.")
    return boto3.client("bedrock-runtime", region_name=region_name)

def get_translate_client(config: Dict[str, Any]) -> Any:
    """Initializes and returns an AWS Translate client."""
    region_name = config.get("region")
    if not region_name:
        raise ValueError("AWS region for Translate must be provided in config.")
    return boto3.client("translate", region_name=region_name)

def get_comprehend_client(config: Dict[str, Any]) -> Any:
    """Initializes and returns an AWS Comprehend client."""
    region_name = config.get("region")
    if not region_name:
        raise ValueError("AWS region for Comprehend must be provided in config.")
    return boto3.client("comprehend", region_name=region_name)

def get_s3_client(config: Dict[str, Any]) -> Any:
    """Initializes and returns an AWS S3 client."""
    region_name = config.get("region")
    if not region_name:
        raise ValueError("AWS region for S3 must be provided in config.")
    return boto3.client("s3", region_name=region_name)

import boto3
from typing import Dict, Any
from vision_client import get_rekognition_client
from vision_models import ImagePayload, DetectTextResponse, TextDetection

def detect_image_text(payload: ImagePayload, config: Dict[str, Any]) -> DetectTextResponse:
    client = get_rekognition_client(config)
    image_bytes = payload.image_bytes

    response = client.detect_text(
        Image={'Bytes': image_bytes}
    )

    text_detections = []
    for text_detection in response.get('TextDetections', []):
        if text_detection['Type'] == 'WORD': # or 'LINE' depending on desired granularity
            text_detections.append(TextDetection(
                detected_text=text_detection['DetectedText'],
                confidence=text_detection['Confidence'] / 100.0,
                bounding_box=text_detection['Geometry']['BoundingBox']
            ))

    return DetectTextResponse(text_detections=text_detections)

import boto3
from typing import Dict, Any
from vision_client import get_rekognition_client
from vision_models import ImagePayload, DetectModerationLabelsResponse, ModerationLabel

def score_image_safety(payload: ImagePayload, config: Dict[str, Any]) -> DetectModerationLabelsResponse:
    client = get_rekognition_client(config)
    image_bytes = payload.image_bytes

    response = client.detect_moderation_labels(
        Image={'Bytes': image_bytes}
    )

    moderation_labels = []
    for label in response.get('ModerationLabels', []):
        moderation_labels.append(ModerationLabel(
            name=label['Name'],
            parent_name=label.get('ParentName'),
            confidence=label['Confidence'] / 100.0
        ))

    return DetectModerationLabelsResponse(moderation_labels=moderation_labels)
